void mergeSort(std::vector<int>& arr, int left, int right) {
    if (left < right) {
        int mid = left + (right - left) / 2;
        mergeSort(arr, left, mid);
        mergeSort(arr, mid + 1, right);
        mergeArrays(arr, left, mid, right);
    }
}

// Function to merge two sorted arrays in-place using a single pointer
void mergeInPlace(std::vector<int>& arr1, std::vector<int>& arr2) {
    // Check if the input arrays are valid
    if (arr1.empty() || arr2.empty()) {
        throw std::invalid_argument("Input arrays cannot be empty.");
    }

    // Check if the arrays are sorted
    for (size_t i = 1; i < arr1.size(); ++i) {
        if (arr1[i] < arr1[i - 1]) {
            throw std::invalid_argument("First array is not sorted.");
        }
    }
    for (size_t i = 1; i < arr2.size(); ++i) {
        if (arr2[i] < arr2[i - 1]) {
            throw std::invalid_argument("Second array is not sorted.");
        }
    }

    // Check if the arrays are of the same size
    if (arr1.size() != arr2.size()) {
        throw std::invalid_argument("Arrays must be of the same size.");
    }

    // Merge the two arrays in-place
    int i = 0;
    int j = 0;
    int k = 0;

    // Create a new array to hold the merged result
    std::vector<int> merged(arr1.size() + arr2.size());

    // Merge the two arrays
    while (i < arr1.size() && j < arr2.size()) {
        if (arr1[i] <= arr2[j]) {
            merged[k++] = arr1[i++];
        } else {
            merged[k++] = arr2[j++];
        }
    }

    // Copy remaining elements
    while (i < arr1.size()) {
        merged[k++] = arr1[i++];
    }
    while (j < arr2.size()) {
        merged[k++] = arr2[j++];
    }

    // Copy the merged array back to the first array
    for (int m = 0; m < merged.size(); ++m) {
        arr1[m] = merged[m];
    }
}

int main() {
    // Example usage
    std::vector<int> arr1 = {1, 3, 5, 7};
    std::vector<int> arr2 = {2, 4, 6, 8};

    try {
        mergeInPlace(arr1, arr2);
        std::cout << "Merged array: ";
        for (int num : arr1) {
            std::cout << num << " ";
        }
        std::cout << std::endl;
    } catch (const std::invalid_argument& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
