pub struct BayesianInference {
    prior_probabilities: HashMap<String, f64>,
    likelihoods: HashMap<String, HashMap<String, f64>>,
}

impl BayesianInference {
    pub fn new() -> Self {
        BayesianInference {
            prior_probabilities: HashMap::new(),
            likelihoods: HashMap::new(),
        }
    }

    pub fn update_prior(&mut self, key: &str, probability: f64) {
        self.prior_probabilities.insert(key.to_string(), probability);
    }

    pub fn update_likelihood(&mut self, key: &str, sub_key: &str, probability: f64) {
        self.likelihoods.entry(key.to_string())
            .or_insert_with(HashMap::new)
            .insert(sub_key.to_string(), probability);
    }

    pub fn calculate_posterior(&self, evidence: &str) -> HashMap<String, f64> {
        let mut posteriors = HashMap::new();

        for (key, prior) in &self.prior_probabilities {
            let mut posterior = *prior;

            if let Some(likelihoods) = self.likelihoods.get(key) {
                if let Some(likelihood) = likelihoods.get(evidence) {
                    posterior *= *likelihood;
                }
            }

            posteriors.insert(key.clone(), posterior);
        }

        posteriors
    }
}
